places=[place(id,name,lat,lng,'Named locality or broad region in the chapter account.','Reference marker only. The guide does not identify a private house, exact camp, cave, field, shrine room, or ancient road. Proposed localities remain uncertain.',['web','atlas-canaan']) for id,name,lat,lng in coordinates]
base=json.loads((OUT/'joshua.json').read_text(encoding='utf-8'))
